SELECT CAST(COUNT(CASE WHEN a.discharge_location IN ('home', 'facility') AND a.discharge_time - a.admittime >= 7 THEN 1 END) AS FLOAT) / NULLIF(COUNT(a.subject_id), 0) AS proportion_of_patients_with_long_stay, PERCENT_RANK() OVER (ORDER BY (a.discharge_time - a.admittime)) AS percentile_rank FROM admissions a JOIN patients p ON a.subject_id = p.subject_id WHERE p.gender = 'M' AND p.age >= 46 AND a.admission_type = 'ED' AND CAST(a.subject_id AS INT) BETWEEN 41 AND 51;